import griffe


class AppendCheckedExtension(griffe.Extension):
    """Griffe extension that tags every collected function's docstring."""

    def on_function_instance(
        self,
        *,
        node,
        func: griffe.Function,
        agent,
        **kwargs,
    ) -> None:
